const now = new Date();
let yesterday = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString().split('T')[0];

// --- Build the list of episodes
const rawEpisodes = $('Get Episodes').first()?.json?.episodes || '[]';
let episodes = [];
let result = [];

try {
  for (const rawEpisode of rawEpisodes) {
    let episode = JSON.parse(rawEpisode)
    if (["user_message", "reply_to_user_message", "send_spontaneous_message"].includes(episode.episode_type)) {
      delete episode.summarized;
      delete episode.triggered_by;
      delete episode.reason;
      episodes.push(episode);
    }
  }

  // Keep only episodes from yesterday
  result = episodes.filter(ep => ep.timestamp.split('T')[0] === yesterday);

  // Sort episodes in chronological order
  result = result.sort((a, b) => a.timestamp.localeCompare(b.timestamp));

} catch (e) {
  throw new Error("Invalid list of episodes");
}

return [{
  json: {
    date: yesterday,
    episodes: result
  }
}];

// Parse and validate the JSON output
// Expected format is:
// [
//   {
//     "date": "2026-06-03",
//     "discussion_summaries": [
//       { 
//         "topic": "topics",
//         "content": "summary string"
//       }
//     ]
//   }
// ]

let result;
const errors = [];

// --- Parse document
const raw = $input.first().json.output || '{}';
try {
  // Strip potential markdown fences
  const cleaned = raw.replace(/```\s*$/i, '').trim();
  result = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Agent did not return valid JSON. Raw output: \n${raw}`);
}

if (!Array.isArray(result))
  throw new Error("Returned document is not a JSON array");

// Check the format of each document
for (const doc of result) {

  // --- Check field "pageContent"
  if (!doc.date || typeof doc.date !== "string") {
    errors.push("date must be a string");
  }

  // --- Check field "discussion_summaries"
  const summaries = doc.discussion_summaries;
  if (!summaries || !Array.isArray(summaries)) {
    errors.push("discussion_summaries must be an array");
  } else {

    for (const summary of summaries) {
      // --- Check field "topic"
      if (!summary.topic || typeof summary.topic !== "string") {
        errors.push("discussion_summaries.*.topic must be a string");
      }

      // --- Check field "content"
      if (!summary.content || typeof summary.content !== "string") {
        errors.push("discussion_summaries.*.content must be a string");
      }
    }
  }
}

if (errors.length > 0)
  throw new Error(`Agent returned a mis-formatted document: ${errors}`);
else
  return result;

// Validated input format:
// [
//   {
//     "date": "2026-06-03",
//     "discussion_summaries": [
//       { 
//         "topic": "topic",
//         "content": "summary string"
//       }
//     ]
//   }
// ]

const rawSummaries = $('Get summaries').first()?.json?.discussion_summaries || '[]';
let summaries = [];

const input = $('Validate output').first()?.json || '[]';
const date = input.date;

try {
  summaries = JSON.parse(rawSummaries);

  // If date already in the summaries, replace the summaries 
  // for that date with the new summaries
  let index = summaries.findIndex(s => s.date === date);
  if (index !== -1) {
    summaries[index] = input;
  } else {
    // Otherwise, add a new entry for the date
    summaries.push(input);
  }
} catch (e) {
  throw new Error("Invalid list of summaries");
}

return [{
  json: {
    summaries
  }
}];
